CREATE OR REPLACE FUNCTION public.advisor_can_read_marketing_photo(p_inspection_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.get_user_role(auth.uid())='property_advisor' AND EXISTS (SELECT 1 FROM public.inspections c JOIN public.inspections ci ON ci.property_id=c.property_id AND ci.market=c.market WHERE c.id=p_inspection_id AND c.inspection_type='captacion' AND ci.inspection_type='check_in' AND ci.inspector_id=auth.uid() AND public.user_has_market(auth.uid(),c.market)); $$;
REVOKE ALL ON FUNCTION public.advisor_can_read_marketing_photo(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.advisor_can_read_marketing_photo(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.get_assigned_marketing_photos(p_checkin_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE ci public.inspections; BEGIN SELECT * INTO ci FROM public.inspections WHERE id=p_checkin_id AND inspection_type='check_in'; IF ci.id IS NULL OR public.get_user_role(auth.uid()) IS DISTINCT FROM 'property_advisor' OR ci.inspector_id IS DISTINCT FROM auth.uid() OR NOT public.user_has_market(auth.uid(),ci.market) THEN RAISE EXCEPTION 'marketing_photos_access_denied'; END IF; RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',p.id,'inspection_id',p.inspection_id,'storage_bucket',p.storage_bucket,'storage_path',p.storage_path,'caption',p.caption,'created_at',p.created_at,'captacion_date',c.created_at) ORDER BY c.created_at DESC,p.sort_order,p.created_at,p.id) FROM public.inspection_photos p JOIN public.inspections c ON c.id=p.inspection_id JOIN public.inspection_sections sec ON sec.id=p.inspection_section_id AND sec.inspection_id=c.id WHERE c.inspection_type='captacion' AND c.property_id=ci.property_id AND c.market=ci.market AND sec.section_key='marketing_photos' AND p.photo_stage='marketing'), '[]'::jsonb); END; $$;
REVOKE ALL ON FUNCTION public.get_assigned_marketing_photos(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.get_assigned_marketing_photos(uuid) TO authenticated,service_role;
CREATE POLICY "Advisor reads assigned property marketing photos" ON public.inspection_photos FOR SELECT TO authenticated USING (photo_stage='marketing' AND public.advisor_can_read_marketing_photo(inspection_id));
CREATE POLICY "Advisor downloads assigned property marketing photos" ON storage.objects FOR SELECT TO authenticated USING (bucket_id='inspection-photos' AND EXISTS (SELECT 1 FROM public.inspection_photos p JOIN public.inspection_sections sec ON sec.id=p.inspection_section_id AND sec.inspection_id=p.inspection_id WHERE p.storage_bucket=objects.bucket_id AND p.storage_path=objects.name AND p.photo_stage='marketing' AND sec.section_key='marketing_photos' AND public.advisor_can_read_marketing_photo(p.inspection_id)));
COMMENT ON FUNCTION public.get_assigned_marketing_photos(uuid) IS 'Read-only marketing gallery for advisors through their assigned check-in, matching property ID and market; no captacion inspection access or write permission.';